  ('4de61e78-0060-558e-aefd-1c1460789dd9', null, (select id from public.skills where slug = 'read-g8-evidence-inference'), null, 'medium',
   $q$Why did no one under thirty remember the lighthouse?$q$, $q$[{"text":"Another artist had painted over it with a new design.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It had faded away so long ago that they had never seen it.","is_correct":true},{"text":"It was added to the mural for the first time last year.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Younger people rarely walked past the Hollis Street bakery.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It had faded away so long ago that they had never seen it.$q$, $q$The passage says the lighthouse "had faded so completely" that younger people did not remember it, so it vanished before they were old enough to notice it. The old photographs show it was part of the original, so it was not new last year.$q$, 'draft', '907d3804-cc16-5957-b6c5-115b7eb8ad05')
